export const SkillCategoryKeyToLabel = {
  'CategoryKey0': 'Programming Language',
  'CategoryKey1': 'Framework',
  'CategoryKey2': 'Database',
  'CategoryKey3': 'Tool',
  'CategoryKey4': 'Soft Skill',
  'CategoryKey5': 'Cloud',
  'CategoryKey6': 'DevOps'
} as const;
export type SkillCategoryKey = keyof typeof SkillCategoryKeyToLabel;

export interface Skill {
  /**
   * @displayName Skill ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  name1: string;
  /**
   * @displayName Category
   * @validationRule Required for create/update operations
   */
  categoryKey: SkillCategoryKey;
  /**
   * @displayName Demand Weight
   * @validationRule Required for create/update operations
   */
  demandWeight: number;
  /**
   * @displayName Is Trending
   * @validationRule Required for create/update operations
   */
  isTrending: boolean;
}

export const _Skill = 'Skill' as const;
